package app.streamnest;
import android.app.*;import android.content.*;import android.os.*;import java.util.*;import org.json.*;
final class OptimizationDataRegression {
 static Bundle run(Instrumentation test)throws Exception{Context c=test.getTargetContext();String original=WatchProgress.preferenceName;WatchProgress.preferenceName="optimization-test-history";
  try{SharedPreferences p=c.getSharedPreferences(WatchProgress.preferenceName,0);SharedPreferences.Editor e=p.edit().clear();for(int n=1;n<=2000;n++)e.putString("movie:tt"+(200000+n),new JSONObject().put("positionMs",120000).put("durationMs",1800000).put("updatedAt",System.currentTimeMillis()-n).toString());e.commit();String key="movie:tt200100";Bundle out=new Bundle();
   long start=SystemClock.elapsedRealtime(),cpu=android.os.Process.getElapsedCpuTime();for(int n=0;n<25;n++){JSONObject row=WatchProgress.records(c).optJSONObject(key);HomeRegression.check(row!=null&&row.getLong("durationMs")==1800000,"Baseline history mismatch");}out.putLong("fullHistory25Ms",SystemClock.elapsedRealtime()-start);out.putLong("fullHistory25CpuMs",android.os.Process.getElapsedCpuTime()-cpu);
   start=SystemClock.elapsedRealtime();cpu=android.os.Process.getElapsedCpuTime();for(int n=0;n<25;n++){JSONObject row=((JSONObject)WatchProgress.class.getDeclaredMethod("record",Context.class,String.class).invoke(null,c,key));HomeRegression.check(row!=null&&row.getLong("durationMs")==1800000,"Selected history mismatch");}out.putLong("oneRecord25Ms",SystemClock.elapsedRealtime()-start);out.putLong("oneRecord25CpuMs",android.os.Process.getElapsedCpuTime()-cpu);
   HomeRegression.check(WatchProgress.read(c,key,0)==120000,"Resume changed");p.edit().putString("removed:tt200100",new JSONObject().put("updatedAt",System.currentTimeMillis()+100).toString()).commit();HomeRegression.check(WatchProgress.read(c,key,0)==0,"Removal marker ignored");p.edit().putLong("source:legacy",12345).commit();HomeRegression.check(WatchProgress.read(c,"source:legacy",0)==12345,"Legacy migration changed");p.edit().putString("movie:tt999","invalid json").commit();HomeRegression.check(WatchProgress.class.getDeclaredMethod("record",Context.class,String.class).invoke(null,c,"movie:tt999")==null,"Invalid history accepted");
   String code="diagnostic-scope-benchmark";start=SystemClock.elapsedRealtime();cpu=android.os.Process.getElapsedCpuTime();String expected="";for(int n=0;n<2000;n++){byte[] bytes=java.security.MessageDigest.getInstance("SHA-256").digest(code.getBytes(java.nio.charset.StandardCharsets.UTF_8));StringBuilder hex=new StringBuilder();for(byte b:bytes)hex.append(String.format(java.util.Locale.ROOT,"%02x",b));expected=hex.toString();}out.putLong("scopePrevious2000Ms",SystemClock.elapsedRealtime()-start);out.putLong("scopePrevious2000CpuMs",android.os.Process.getElapsedCpuTime()-cpu);
   start=SystemClock.elapsedRealtime();cpu=android.os.Process.getElapsedCpuTime();for(int n=0;n<2000;n++)HomeRegression.check(DiagnosticScope.id(code).equals(expected),"Pairing scope changed");out.putLong("scopeCached2000Ms",SystemClock.elapsedRealtime()-start);out.putLong("scopeCached2000CpuMs",android.os.Process.getElapsedCpuTime()-cpu);
   out.putString("result","PASS: selected-row lookup matches2000-record scan, removal/legacy/invalid cases preserved; cached scope matches SHA256");return out;
  }finally{c.getSharedPreferences(WatchProgress.preferenceName,0).edit().clear().commit();WatchProgress.preferenceName=original;DiagnosticScope.clear();}
 }
}
